import { createRoot } from "react-dom/client";
import { MotionConfig } from "motion/react";
import "@rain-next/foundations/tokens.css";
import "@rain-next/foundations/typography.css";
import "@rain-next/foundations/focus.css";
import "@rain-next/ui/charts/styles.css";
import "./chart-examples.css";
import { ComparisonVariant } from "./chart-variants/comparison";
import { useChartReducedMotion, type VariantSettings } from "./chart-variants/shared";

function App() {
  const [settings, setSettings] = useState<VariantSettings>({});
  const [curveName, setCurveName] = useState<string | undefined>(undefined);
  const userReduced = useChartReducedMotion();
  const [active, setActive] = useState(!document.hidden);
  useEffect(() => {
    const change = () => setActive(!document.hidden);
    document.addEventListener("visibilitychange", change);
    return () => document.removeEventListener("visibilitychange", change);
  }, []);
  return <MotionConfig reducedMotion="user">
    <main className="rain-chart" data-recipe="monochrome-blue" style={{ maxWidth: 880, margin: "auto", padding: "var(--rain-space-24)" }}>
      <ComparisonVariant variantId="scatter-default" recipe="monochrome-blue" revision={0} replay={0} reduced={true || userReduced} active={active} settings={settings} onSettingsChange={patch => setSettings(previous => ({ ...previous, ...patch }))} curveName={curveName} onCurveChange={setCurveName} />
    </main>
  </MotionConfig>;
}
createRoot(document.getElementById("root")!).render(<App />);对应官网示例（新标签页打开）

